import assert from "node:assert/strict";
import { readdirSync, readFileSync } from "node:fs";
import { test } from "node:test";
import { browserOpsFromWasm, buildPlan, initLowering, PlanBuildError, SUPPORTED_OPS } from "../src/engine/lowering.ts";

// RFC-004, second layer: request -> PlanGraph is built by ONE implementation (Rust `geo-plan`). The gateway links it natively; this page runs the same
// code as WebAssembly. The golden fixtures were generated by the NATIVE builder (crates/geo-lowering/tests/request_plans.rs); the real wasm module
// must reproduce every plan byte for byte, every refusal with the same structured code, and the same browser capability verdict.
await initLowering(readFileSync(new URL("../src/engine/generated/geo_lowering.wasm", import.meta.url)));

const dir = new URL("../../crates/geo-plan/fixtures/requests/", import.meta.url);
const sources = JSON.parse(readFileSync(new URL("_sources.json", dir), "utf8")) as Record<string, unknown>;
const fixtures = readdirSync(dir).filter((f) => f.endsWith(".json") && !f.startsWith("_")).sort();

test("there are golden request fixtures", () => {
  assert.ok(fixtures.length >= 35, `found ${fixtures.length}`);
});

for (const f of fixtures) {
  const fx = JSON.parse(readFileSync(new URL(f, dir), "utf8")) as {
    name: string; request: unknown;
    expected: { plan_json?: string; browser_missing_ops?: string[]; error?: { code: string; status: number; legacy: string } };
  };
  test(`wasm builder == native builder: ${fx.name}`, () => {
    if (fx.expected.error) {
      assert.throws(
        () => buildPlan(fx.request, sources),
        (e: unknown) => e instanceof PlanBuildError && e.code === fx.expected.error!.code && e.status === fx.expected.error!.status && e.legacy === fx.expected.error!.legacy,
        fx.name,
      );
      return;
    }
    const built = buildPlan(fx.request, sources);
    assert.equal(built.planJson, fx.expected.plan_json, "the plan must be byte-identical to the native builder's");
    assert.deepEqual(built.browserMissingOps, fx.expected.browser_missing_ops);
  });
}

test("the browser capability list in the page is the one the Rust code reports", () => {
  assert.deepEqual([...SUPPORTED_OPS].sort(), [...browserOpsFromWasm()].sort());
});

test("malformed requests are refused as structured errors, never as a panic of the wasm module", () => {
  const garbage: unknown[] = [null, 7, "x", [], {}, { kind: 1 }, { kind: "features" }, { kind: "features", source: "places", bbox: "no", crs: "OGC:CRS84" },
    { kind: "features", source: "places", bbox: [1, 2, 3], crs: "OGC:CRS84" }, { kind: "features", source: "places", bbox: [Number.NaN, 0, 1, 1], crs: "OGC:CRS84" },
    { kind: "features", source: "places", bbox: [0, 0, 1, 1], crs: "OGC:CRS84", filter: { column: "category", op: "eq", value: { deep: { nest: [1] } } } },
    { kind: "features", source: "places", bbox: [0, 0, 1, 1], crs: "OGC:CRS84", limit: -5 }, { kind: "features", source: "places", bbox: [0, 0, 1, 1], crs: "OGC:CRS84", limit: 1e30 }];
  for (const g of garbage) {
    assert.throws(() => buildPlan(g, sources), (e: unknown) => e instanceof PlanBuildError && /^[A-Z_]+$/.test(e.code), JSON.stringify(g));
  }
  // and the module is still usable afterwards
  assert.ok(buildPlan({ kind: "count", source: "places", bbox: [106.69, 10.77, 106.71, 10.79], crs: "OGC:CRS84" }, sources).planJson.length > 100);
});

test("a request never smuggles SQL: values stay literals in the plan, identifiers must be columns of the dataset", () => {
  const evil = "x'; DROP TABLE y; --";
  const ok = buildPlan({ kind: "features", source: "places", bbox: [106.69, 10.77, 106.71, 10.79], crs: "OGC:CRS84", filter: { column: "category", op: "eq", value: evil } }, sources);
  assert.ok(ok.planJson.includes(evil), "the value is carried as a string literal of the plan");
  assert.throws(
    () => buildPlan({ kind: "features", source: "places", bbox: [106.69, 10.77, 106.71, 10.79], crs: "OGC:CRS84", filter: { column: 'category"; DROP TABLE y; --', op: "eq", value: "x" } }, sources),
    (e: unknown) => e instanceof PlanBuildError && e.code === "INVALID_FIELD",
  );
});
